 if(!tasks.work_execution||offer.domain!="tasks"||offer.kind!="work_task_offered"||accepted.has_value()!=execution.has_value())return common_failure("InvalidWorkTaskBinding");const auto*o=tasks.work_execution->work_task_offers.find(offer.id);if(!o||!same(o->authorization.program_ref,program)||!header(common,offer.id,"work_task_offered"))return common_failure("WorkTaskOfferBindingMissing");if(!accepted)return common_success();if(accepted->domain!="tasks"||accepted->kind!="work_task_accepted"||execution->domain!="tasks"||execution->kind!="work_accepted")return common_failure("WorkTaskAcceptanceBindingMismatch");const auto*a=tasks.work_execution->work_task_acceptances.find(accepted->id);const auto*w=tasks.work_execution->acceptances.find(execution->id);if(!a||!w||w->authorization.accepted_task_id!=a->task_id||!same(w->original_task_acceptance.source_ref,*accepted)||!same(a->offered_task_ref,offer))return common_failure("WorkTaskAcceptanceBindingMismatch");return validate_work_task_identity_source(common,tasks,program,offer,a->task_id,false);
