 auto approval=read_verified_governance_program_approval(x.governance,o.authorization.program_ref);if(!approval.ok)return {false,{},approval.error};auto plan=approved_plan(x,*approval.value.approval,*approval.value.specification,actor);if(!plan.ok)return {false,{},plan.error};task.deadline_tick=deadline(plan.value).tick;
 if(!tasks.tasks.insert(task.id,std::move(task))||!tasks.work_execution->work_task_acceptances.insert(fact.value,std::move(accepted)))return fail<StableId>("DuplicateWorkTaskAcceptance");valid=common.append_fact({fact.value,"work_task_accepted","tasks"});if(!valid.ok)return {false,{},valid.error};WorkAuthorizationRef authorization{o.authorization.program_ref,o.authorization.target_line_id,o.authorization.terms_revision,task_id.value};AcceptingWorkTaskRead accepting(reader,originals);auto work=begin_work_in_candidate(common,tasks,accepting,expenses,authorization,now.value);if(!work.ok)return work;const auto*episode=tasks.work_execution->episodes.find(work.value);if(!episode)return fail<StableId>("WorkAcceptanceMissing");auto bound=bind_governance_execution_in_candidate(common,programs,x.governance,o.authorization.program_ref.id,ref,SourceRef{"tasks","work_task_accepted",fact.value},SourceRef{"tasks","work_accepted",episode->acceptance_source_ref});if(!bound.ok)return {false,{},bound.error};
